-- Dữ liệu mẫu BSC cho tổ chức demo (Demo Company) — 12 chỉ tiêu, 3 mỗi lĩnh vực, trải 6 đợt
-- Tháng 1→6/2026, kèm kết quả đợt đã chốt.
--
-- V2 chỉ cho mỗi lĩnh vực ĐÚNG MỘT chỉ tiêu trùng tên lĩnh vực, nên bản đồ chiến lược và xương cá
-- ở tab Thống kê → Thẻ điểm BSC chỉ vẽ được 4 ô, không đọc ra chiến lược nào. File này dựng thêm
-- 8 hạng mục, cây thẻ điểm ba cấp (Công ty → 2 phòng → 4 team) và kết quả của từng đợt.
--
-- Số liệu KHÔNG bịa: cấu trúc dựng bằng script, rồi chạy chính "Tính lại" và "Chốt" của hệ thống
-- trên DB dev; file này là ảnh chụp kết quả đó, sinh lại được bằng scripts gen_bsc_migration.py.
-- Mục tiêu từng dòng suy ngược từ giá trị thực đạt đo được (target = actual / hệ số cố định) để
-- %đạt trải 62–112% thay vì kịch trần 150% — mục tiêu vốn là thứ người dùng đặt.
--
-- CHỈ chạm tổ chức demo. Bỏ qua toàn bộ nếu tổ chức đó đã có thẻ điểm đơn vị (ai đó đã dựng tay
-- hoặc đã dùng thật) — không đè lên dữ liệu của người khác.

CREATE TEMP TABLE bsc_demo_guard ON COMMIT DROP AS
SELECT NOT EXISTS (
    SELECT 1 FROM bsc_scorecards s
    WHERE s.organization_id = '11111111-1111-1111-1111-111111111111' AND s.level = 'UNIT' AND s.deleted_at IS NULL
) AS ok;

-- ── 1. 12 hạng mục BSC: đổi tên 4 hạng mục gốc thành mục tiêu đầu mỗi nhóm, thêm 8 ────────
UPDATE bsc_perspectives SET name = v.name, display_order = v.ord, updated_at = NOW()
FROM (VALUES ('FINANCIAL', 'Doanh thu', 1), ('CUSTOMER', 'Mức hài lòng', 4),
             ('INTERNAL_PROCESS', 'Chất lượng bàn giao', 7), ('LEARNING_GROWTH', 'Năng lực đội ngũ', 10)
     ) AS v(code, name, ord)
WHERE bsc_perspectives.code = v.code AND bsc_perspectives.organization_id = '11111111-1111-1111-1111-111111111111'
  AND (SELECT ok FROM bsc_demo_guard);

-- Màu và icon lấy theo hạng mục gốc cùng lĩnh vực, không sinh tên icon lạ.
INSERT INTO bsc_perspectives (id, organization_id, code, fixed_perspective, name, description,
                              color, icon, display_order, status, created_at, updated_at)
SELECT v.id::uuid, base.organization_id, v.code, v.fp, v.name, v.descr,
       base.color, base.icon, v.ord, 'ACTIVE', NOW(), NOW()
FROM (VALUES
    ('6bfbb8f0-943b-960f-ca24-6d29c20c420b', 'FIN_COST', 'FINANCIAL', 'Chi phí vận hành', 'Chi phí trên mỗi đơn vị sản lượng', 2),
    ('84aa810a-2c85-018a-f4c7-7b64e6a0d1ad', 'FIN_CASHFLOW', 'FINANCIAL', 'Dòng tiền', 'Dòng tiền thuần từ hoạt động', 3),
    ('a90182a2-33cf-c5b2-9e3c-d15993ae2fc6', 'CUS_NEW', 'CUSTOMER', 'Khách hàng mới', 'Số khách hàng ký mới trong kỳ', 5),
    ('e9709fc9-f6d3-b97a-38d3-1169a8a20df6', 'CUS_RETENTION', 'CUSTOMER', 'Giữ chân khách hàng', 'Tỉ lệ khách hàng tiếp tục hợp tác', 6),
    ('26ba7a38-5308-d4a6-27d1-a3c2d55912c1', 'INT_CYCLE_TIME', 'INTERNAL_PROCESS', 'Thời gian xử lý', 'Thời gian trung bình hoàn tất một yêu cầu', 8),
    ('0fdb740b-018f-9641-1575-f1eb990a97e9', 'INT_COMPLIANCE', 'INTERNAL_PROCESS', 'Tuân thủ quy trình', 'Tỉ lệ việc làm đúng quy trình ban hành', 9),
    ('7df260a9-09cf-75c1-86a4-1866a1605ae5', 'LNG_TRAINING', 'LEARNING_GROWTH', 'Đào tạo nội bộ', 'Số giờ đào tạo bình quân mỗi người', 11),
    ('7ad63943-85af-a2f6-34b9-91e60a975b0d', 'LNG_RETENTION', 'LEARNING_GROWTH', 'Giữ chân nhân sự', 'Tỉ lệ nhân sự ở lại sau 12 tháng', 12)
) AS v(id, code, fp, name, descr, ord)
JOIN bsc_perspectives base ON base.code = v.fp AND base.organization_id = '11111111-1111-1111-1111-111111111111'
WHERE NOT EXISTS (SELECT 1 FROM bsc_perspectives x
                  WHERE x.code = v.code AND x.organization_id = '11111111-1111-1111-1111-111111111111')
  AND (SELECT ok FROM bsc_demo_guard);

-- ── 2. Thẻ công ty gắn vào đơn vị GỐC ──────────────────────────────────────────────────────
-- BscScoringService.resolveScorecard chỉ nhận bộ gắn ĐÚNG đơn vị; thẻ công ty của V2 không gắn
-- đơn vị nào nên không bộ tiêu chí nào hiệu lực cho ai, và mọi ô BSC ở tab Thống kê trống trơn.
INSERT INTO bsc_scorecard_org_units (scorecard_id, org_unit_id)
SELECT s.id, 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'
FROM bsc_scorecards s
WHERE s.level = 'COMPANY' AND s.deleted_at IS NULL AND s.organization_id = '11111111-1111-1111-1111-111111111111'
  AND NOT EXISTS (SELECT 1 FROM bsc_scorecard_org_units x WHERE x.scorecard_id = s.id)
  AND (SELECT ok FROM bsc_demo_guard);

-- Dựng lại chỉ tiêu thẻ công ty: 4 dòng của V2 → 12 dòng, trọng số vẫn cộng tròn 100 và giữ
-- đúng tỉ trọng lĩnh vực cũ (30/25/30/15).
DELETE FROM bsc_scorecard_perspectives WHERE scorecard_id IN (
    SELECT id FROM bsc_scorecards
    WHERE level = 'COMPANY' AND organization_id = '11111111-1111-1111-1111-111111111111'
) AND (SELECT ok FROM bsc_demo_guard);

-- ── 3. Thẻ điểm đơn vị: Công ty → Phòng IT / Phòng Truyền Thông → 4 team, mỗi đợt một bộ ──
-- Hai câu INSERT theo CẤP: thẻ team trỏ cha là thẻ phòng, mà một câu INSERT ... SELECT đọc trạng
-- thái bảng lúc bắt đầu nên không nhìn thấy thẻ phòng vừa chèn trong chính nó.
